package android.widget;import android.content.Context;import android.graphics.*;import android.graphics.drawable.Drawable;import android.view.View;public class TextView extends View {protected CharSequence text="";private int compoundPadding;public TextView(Context c){super(c);}public void setText(CharSequence t){text=t;emit("text",t);}public CharSequence getText(){return text;}public void setTextColor(int c){emit("text_color",c);}public void setTextSize(float s){emit("text_size",s);}public void setTypeface(Typeface t){emit("typeface",t);}public void setAllCaps(boolean b){emit("all_caps",b);}public void setSingleLine(boolean b){emit("single_line",b);}public void setHint(CharSequence s){emit("hint",s);}public void setGravity(int g){emit("gravity",g);}public void setCompoundDrawablePadding(int p){compoundPadding=p;emit("compound_padding",p);}public int getCompoundDrawablePadding(){return compoundPadding;}public void setCompoundDrawables(Drawable l,Drawable t,Drawable r,Drawable b){emit("compound_drawables",l,t,r,b);}}
